package statshouse

import (
	"math"
	"strconv"
)

// Advanced feature.
// Encodes float as a raw tag in a special format, used by Statshouse.
// Ordering of all float values is preserved after encoding.
// Except all NaNs map to single value which is > +inf, and both zeroes map to 0.
func LexEncode(x float32) int32 {
	if x == 0 {
		return 0 // replace -0 with +0
	}
	if math.IsNaN(float64(x)) {
		return 0x7fc00000 // replace all NaNs with single positive quiet NaN
	}
	bits := math.Float32bits(x)
	if x < 0 {
		// flip all except signbit so bigger negatives go before smaller ones
		bits ^= 0x7fffffff
	}
	return int32(bits)
}

func LexEncodeStr(x float32) string {
	return strconv.Itoa(int(LexEncode(x)))
}

func LexDecode(x int32) float32 {
	bits := uint32(x)
	if x < 0 {
		bits ^= 0x7fffffff
	}
	return math.Float32frombits(bits)
}

package statshouse

import (
	"encoding/binary"
	"errors"
	"net"
	"sync"
	"sync/atomic"
	"time"
)

const (
	tcpPrefix              = "statshousev"
	tcpMagicV2             = byte('2')
	defaultDialTimeout     = 5 * time.Second
	defaultReconnectDelay  = time.Second
	defaultWriteTimeout    = 15 * time.Second
	writeTimeoutAccuracy   = 2 * time.Second
	defaultStuckReconDelay = 30 * time.Second
)

type netConn interface {
	Write(b []byte) ([]byte, error)
	Close() error
}

// Client manages metric aggregation and transport to a StatsHouse agent.
type datagramConn struct { // either UDP or unixgram
	net.Conn
}

type tcpConn struct {
	wouldBlockSize atomic.Int32

	*Client
	app       string
	env       string
	handshake string // precomputed reconnect key (copy every connect for safety)

	poolMu  sync.Mutex
	pool    addressPool
	w       chan []byte
	reconCh chan struct{}

	closed   atomic.Bool
	closeErr chan error
}

type tcpPoolConn struct {
	primPtr   **tcpConn // ptr to primary, nonblocking swap
	secPtr    **tcpConn // ptr to secondary, nonblocking swap
	primary   *tcpConn
	secondary *tcpConn
	closed    chan struct{}
	closeOnce sync.Once
}

func (d *tcpPoolConn) Write(b []byte) ([]byte, error) {
	if len(b) == 0 {
		return b, nil
	}
	select {
	case <-d.closed:
		return make([]byte, cap(b)), errWriteAfterClose
	default:
	}
	b, err := (*d.primPtr).Write(b)
	if err == nil {
		return b, nil
	}
	if !errors.Is(err, errWouldBlock) {
		return b, err
	}
	b, err = (*d.secPtr).Write(b)
	if err == nil {
		select {
		case (*d.primPtr).reconCh <- struct{}{}:
		default:
		}
		d.primPtr, d.secPtr = d.secPtr, d.primPtr
		return b, nil
	}
	if errors.Is(err, errWouldBlock) {
		d.primary.wouldBlockSize.Add(int32(len(b)))
		return b, errWouldBlock
	}
	return b, err
}

func (d *tcpPoolConn) Close() (err error) {
	d.closeOnce.Do(func() {
		close(d.closed)
		err = d.primary.Close()
		err2 := d.secondary.Close()
		if err == nil {
			err = err2
		}
	})
	return
}

func (c *Client) netDial() (netConn, error) {
	targets, err := resolveDialTargets(c.network, c.addr)
	if err != nil {
		c.rareLog("[statshouse] resolve address %q: %v", c.addr, err)
		return nil, err
	}
	c.dialTargets = targets

	if c.network == "tcp" {
		return c.netDialTCP()
	}
	addr := c.addr
	if len(c.dialTargets) > 0 {
		addr = c.dialTargets[0]
	}
	conn, err := net.Dial(c.network, addr)
	if err != nil {
		c.rareLog("[statshouse] failed to dial statshouse: %v", err)
		return nil, err
	}
	return &datagramConn{Conn: conn}, nil
}

func (c *Client) netDialTCP() (netConn, error) {
	primaryPool, secondaryPool := newAddressPools(c.dialTargets)
	handshake := buildTCPHandshakeV2(c.hostTag)
	primary := &tcpConn{
		Client:    c,
		app:       c.app,
		env:       c.env,
		handshake: handshake,
		pool:      primaryPool,
		w:         make(chan []byte, tcpConnBucketCount),
		reconCh:   make(chan struct{}, 1),
		closeErr:  make(chan error, 1),
	}
	go primary.send()

	secondary := &tcpConn{
		Client:    c,
		app:       c.app,
		env:       c.env,
		handshake: handshake,
		pool:      secondaryPool,
		w:         make(chan []byte, tcpConnBucketCount),
		reconCh:   make(chan struct{}, 1),
		closeErr:  make(chan error, 1),
	}
	go secondary.send()
	poolConn := &tcpPoolConn{
		primary:   primary,
		secondary: secondary,
		closed:    make(chan struct{}),
	}
	poolConn.primPtr = &poolConn.primary
	poolConn.secPtr = &poolConn.secondary
	go poolConn.runDNSRefresh(c.network, c.addr)
	return poolConn, nil
}

func (d *tcpPoolConn) runDNSRefresh(network, addr string) {
	ticker := time.NewTicker(time.Minute)
	defer ticker.Stop()
	cl := d.primary.Client
	for {
		select {
		case <-d.closed:
			return
		case <-ticker.C:
			targets, err := resolveDialTargets(network, addr)
			if err != nil {
				cl.rareLog("[statshouse] dns refresh resolve %q: %v", addr, err)
				continue
			}
			primaryPool, secondaryPool := newAddressPools(targets)
			d.primary.replacePool(primaryPool)
			d.secondary.replacePool(secondaryPool)
		}
	}
}

func (t *datagramConn) Write(b []byte) ([]byte, error) {
	_, err := t.Conn.Write(b[tlInt32Size:]) // skip data length
	return b, err
}

func (t *datagramConn) Close() error {
	return t.Conn.Close()
}

func (t *tcpConn) Write(b []byte) (_ []byte, err error) {
	if len(b) == 0 {
		return b, nil
	}
	if t.closed.Load() {
		return b, errWriteAfterClose
	}
	n := cap(b)
	select {
	case t.w <- b:
		return make([]byte, n), nil
	default:
		return b, errWouldBlock
	}
}

func (t *tcpConn) Close() error {
	if t.closed.CompareAndSwap(false, true) {
		close(t.w)
	}
	return <-t.closeErr
}

func (t *tcpConn) send() {
	var conn net.Conn
	var err error
	var lastDial time.Time
	var lastStuckRecon = time.Now()
	var writeDeadline time.Time
loop:
	for {
		select {
		case <-t.reconCh:
			if lastStuckRecon.Add(defaultStuckReconDelay).After(time.Now()) {
				continue
			}
			if conn != nil {
				_ = conn.Close()
				conn = nil
				writeDeadline = time.Time{}
				lastStuckRecon = time.Now()
			}
			continue
		default:
		}
		if conn == nil {
			time.Sleep(defaultReconnectDelay - time.Since(lastDial))
			lastDial = time.Now()
			conn, err = t.reconnect()
			if err != nil {
				if t.closed.Load() {
					break loop
				}
				if !errors.Is(err, errEmptyAddr) { // ignore secondary without address
					t.rareLog("[statshouse] failed to dial statshouse: %v", err)
				}
				continue
			}
			writeDeadline = time.Time{}
		}
		if defaultWriteTimeout-time.Until(writeDeadline) > writeTimeoutAccuracy {
			deadline := time.Now().Add(defaultWriteTimeout)
			if err = conn.SetWriteDeadline(deadline); err != nil {
				t.rareLog("[statshouse] failed to set write deadline: %v", err)
				_ = conn.Close()
				conn = nil
				writeDeadline = time.Time{}
				continue
			}
			writeDeadline = deadline
		}
		buf, ok := <-t.w
		if !ok {
			break
		}
		if _, err = conn.Write(buf); err != nil {
			t.rareLog("[statshouse] failed to send data to statshouse: %v", err)
			_ = conn.Close()
			conn = nil
			writeDeadline = time.Time{}
			continue // not resend for tcp connect
		}
		t.reportWouldBlockIfAny(conn, buf)
	}
	err = nil
	if conn != nil {
		err = conn.Close()
	}
	t.closeErr <- err
}

func (t *tcpConn) reconnect() (net.Conn, error) {
	t.poolMu.Lock()
	addr, ok := t.pool.pick()
	t.poolMu.Unlock()
	if !ok {
		return nil, errEmptyAddr
	}

	conn, err := (&net.Dialer{Timeout: defaultDialTimeout}).Dial("tcp", addr)
	if err != nil {
		t.rareLog("[statshouse] failed to dial statshouse: %v", err)
		return nil, err
	}
	if _, err = conn.Write([]byte(t.handshake)); err != nil {
		t.rareLog("[statshouse] failed to send header to statshouse: %v", err)
		_ = conn.Close()
		return nil, err
	}
	return conn, nil
}

func (t *tcpConn) replacePool(p addressPool) {
	t.poolMu.Lock()
	t.pool = p
	t.poolMu.Unlock()
}

func (t *tcpConn) reportWouldBlockIfAny(conn net.Conn, buf []byte) {
	n := t.wouldBlockSize.Swap(0)
	if n == 0 {
		return
	}
	// report data loss
	t.rareLog("[statshouse] lost %v bytes", n)
	p := packet{
		buf:     buf[:batchHeaderLen],
		maxSize: cap(buf),
	}
	k := metricKeyTransport{
		name: "__src_client_write_err",
	}
	fillTag(&k, "0", t.env)
	fillTag(&k, "1", "1")   // lang: golang
	fillTag(&k, "2", "1")   // kind: would block
	fillTag(&k, "3", t.app) // application name
	fillTag(&k, "_h", t.hostTag)
	p.sendValues(nil, &k, "", 0, 0, []float64{float64(n)})
	p.writeBatchHeader()
	if _, err := conn.Write(p.buf); err != nil {
		t.rareLog("[statshouse] failed to send data to statshouse: %v", err)
	}
}

func buildTCPHandshakeV2(hostTag string) string {
	buf := make([]byte, 0, len(tcpPrefix)+1+tlInt32Size+len(hostTag))
	buf = append(buf, tcpPrefix...)
	buf = append(buf, tcpMagicV2)
	var lenH [tlInt32Size]byte
	binary.LittleEndian.PutUint32(lenH[:], uint32(len(hostTag)))
	buf = append(buf, lenH[:]...)
	buf = append(buf, hostTag...)
	return string(buf)
}

func forceValidHostTag(s string) string {
	if len(s) <= maxHostTagLen {
		return s
	}
	return s[:maxHostTagLen]
}

package statshouse

import (
	"sync"

	"pgregory.net/rand"
)

type bucket struct {
	// readonly
	c       *Client
	k       metricKey
	kn      metricKeyNamed
	maxSize int

	mu          sync.Mutex // taken before [Client.mu]
	r           *rand.Rand
	tsUnixSec   uint32
	attached    bool
	count       float64
	valueCount  int
	uniqueCount int
	value       []float64
	unique      []int64
	stop        []string

	// access only by "send" goroutine, not protected
	countToSend       float64
	valueCountToSend  int
	uniqueCountToSend int
	valueToSend       []float64
	uniqueToSend      []int64
	stopToSend        []string
	emptySendCount    int
}

type metricKey struct {
	name string
	tags Tags
}

type metricKeyNamed struct {
	name string
	tags internalTags
}

type internalTags [maxTags][2]string

func (b *bucket) appendValue(s ...float64) {
	for _, v := range s {
		b.valueCount++
		if len(b.value) < b.maxSize {
			b.value = append(b.value, v)
		} else {
			if b.r == nil {
				b.r = rand.New()
			}
			if n := b.r.Intn(b.valueCount); n < len(b.value) {
				b.value[n] = v
			}
		}
	}
}

func (b *bucket) appendUnique(s ...int64) {
	for _, v := range s {
		b.uniqueCount++
		if len(b.unique) < b.maxSize {
			b.unique = append(b.unique, v)
		} else {
			if b.r == nil {
				b.r = rand.New()
			}
			if n := b.r.Intn(b.uniqueCount); n < len(b.unique) {
				b.unique[n] = v
			}
		}
	}
}

func (b *bucket) swapToSend(nowUnixSec uint32) {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.tsUnixSec = nowUnixSec
	b.count, b.countToSend = 0, b.count
	b.valueCount, b.valueCountToSend = 0, b.valueCount
	b.uniqueCount, b.uniqueCountToSend = 0, b.uniqueCount
	b.value, b.valueToSend = b.valueToSend[:0], b.value
	b.unique, b.uniqueToSend = b.uniqueToSend[:0], b.unique
	b.stop, b.stopToSend = b.stopToSend[:0], b.stop
}

func (b *bucket) send(c *Client, tsUnixSec uint32) {
	var k metricKeyTransport
	if b.k.name != "" {
		k.name = b.k.name
		for i, v := range b.k.tags {
			fillTag(&k, tagIDs[i], v)
		}
	} else if b.kn.name != "" {
		k.name = b.kn.name
		for _, v := range b.kn.tags {
			fillTag(&k, v[0], v[1])
		}
	} else {
		c.rareLog("[statshouse] empty metric name, discarding")
		return
	}
	if !k.hasEnv {
		fillTag(&k, "0", c.env)
	}
	if !k.hasHost {
		fillTag(&k, "_h", c.hostTag)
	}
	if b.countToSend > 0 {
		c.sendCounter(c, &k, "", b.countToSend, tsUnixSec)
	}
	c.sendValues(c, &k, "", float64(b.valueCountToSend), tsUnixSec, b.valueToSend)
	c.sendUniques(c, &k, "", float64(b.uniqueCountToSend), tsUnixSec, b.uniqueToSend)
	for _, skey := range b.stopToSend {
		c.sendCounter(c, &k, skey, 1, tsUnixSec)
	}
}

func (b *bucket) emptySend() bool {
	return b.countToSend == 0 &&
		len(b.valueToSend) == 0 &&
		len(b.uniqueToSend) == 0 &&
		len(b.stopToSend) == 0
}

package statshouse

import (
	"context"
	"net"
	"strings"

	"pgregory.net/rand"
)

type addressPool struct {
	addrs []string
	head  int
}

func newAddressPools(addrs []string) (primary addressPool, secondary addressPool) {
	mid := (len(addrs) + 1) / 2 // primary gets the extra element
	primary = addressPool{addrs: addrs[:mid]}
	if mid < len(addrs) {
		secondary = addressPool{addrs: addrs[mid:]}
	}
	return primary, secondary
}

func (p *addressPool) len() int {
	return len(p.addrs)
}

func (p *addressPool) pick() (string, bool) {
	n := len(p.addrs)
	if n == 0 {
		return "", false
	}
	addr := p.addrs[p.head]
	p.head = (p.head + 1) % n
	return addr, true
}

func resolveDialTargets(network, rawAddr string) ([]string, error) {
	if rawAddr == "" {
		return []string{""}, nil
	}
	if network == "unixgram" {
		return []string{rawAddr}, nil
	}
	if network == "udp" {
		// For UDP we intentionally keep DNS names unresolved and dial hostnames directly.
		return strings.Split(rawAddr, ","), nil
	}
	var addrs []string
	for _, ep := range strings.Split(rawAddr, ",") {
		host, port, err := net.SplitHostPort(strings.TrimSpace(ep))
		if err != nil {
			return []string{""}, err
		}
		if ip := net.ParseIP(host); ip != nil {
			addrs = append(addrs, net.JoinHostPort(host, port))
			continue
		}
		ctx := context.Background()
		recs, err := net.DefaultResolver.LookupIPAddr(ctx, host)
		if err != nil {
			return []string{""}, err
		}
		for _, ipa := range recs {
			addrs = append(addrs, net.JoinHostPort(ipa.String(), port))
		}
	}
	r := rand.New()
	r.Shuffle(len(addrs), func(i, j int) {
		addrs[i], addrs[j] = addrs[j], addrs[i]
	})
	return addrs, nil
}

package statshouse

import (
	"encoding/binary"
	"math"
	"net"
	"runtime"

	"github.com/VKCOM/statshouse-go/internal/basictl"
)

type packet struct {
	buf        []byte
	maxSize    int
	batchCount int
}

type metricKeyTransport struct {
	name    string
	tags    internalTags
	numSet  int
	hasEnv  bool
	hasHost bool
}

func (p *packet) sendCounter(c *Client, k *metricKeyTransport, skey string, counter float64, tsUnixSec uint32) {
	_ = p.writeHeader(c, k, skey, counter, tsUnixSec, counterFieldsMask, 0)
}

func (p *packet) sendUniques(c *Client, k *metricKeyTransport, skey string, counter float64, tsUnixSec uint32, values []int64) {
	fieldsMask := uniqueFieldsMask
	if counter != 0 && counter != float64(len(values)) {
		fieldsMask |= counterFieldsMask
	}
	for len(values) > 0 {
		left := p.writeHeader(c, k, skey, counter, tsUnixSec, fieldsMask, tlInt32Size+tlInt64Size)
		if left < 0 {
			return // header did not fit into empty buffer
		}
		writeCount := 1 + left/tlInt64Size
		if writeCount > len(values) {
			writeCount = len(values)
		}
		p.buf = basictl.NatWrite(p.buf, uint32(writeCount))
		for i := 0; i < writeCount; i++ {
			p.buf = basictl.LongWrite(p.buf, values[i])
		}
		values = values[writeCount:]
	}
}

func (p *packet) sendValues(c *Client, k *metricKeyTransport, skey string, counter float64, tsUnixSec uint32, values []float64) {
	fieldsMask := valueFieldsMask
	if counter != 0 && counter != float64(len(values)) {
		fieldsMask |= counterFieldsMask
	}
	for len(values) > 0 {
		left := p.writeHeader(c, k, skey, counter, tsUnixSec, fieldsMask, tlInt32Size+tlFloat64Size)
		if left < 0 {
			return // header did not fit into empty buffer
		}
		writeCount := 1 + left/tlFloat64Size
		if writeCount > len(values) {
			writeCount = len(values)
		}
		p.buf = basictl.NatWrite(p.buf, uint32(writeCount))
		for i := 0; i < writeCount; i++ {
			p.buf = basictl.DoubleWrite(p.buf, values[i])
		}
		values = values[writeCount:]
	}
}

func (p *packet) writeBatchHeader() {
	binary.LittleEndian.PutUint32(p.buf, uint32(len(p.buf)-tlInt32Size))
	binary.LittleEndian.PutUint32(p.buf[tlInt32Size:], metricsBatchTag)
	binary.LittleEndian.PutUint32(p.buf[2*tlInt32Size:], 0) // fields_mask
	binary.LittleEndian.PutUint32(p.buf[3*tlInt32Size:], uint32(p.batchCount))
}

func (p *packet) writeHeaderImpl(k *metricKeyTransport, skey string, counter float64, tsUnixSec uint32, fieldsMask uint32) {
	if tsUnixSec != 0 {
		fieldsMask |= tsFieldsMask
	}
	p.buf = basictl.NatWrite(p.buf, fieldsMask)
	p.buf = basictl.StringWriteTruncated(p.buf, k.name)
	// can write more than maxTags pairs, but this is allowed by statshouse
	numSet := k.numSet
	if skey != "" {
		numSet++
	}
	p.buf = basictl.NatWrite(p.buf, uint32(numSet))
	if skey != "" {
		p.writeTag("_s", skey)
	}
	for i := 0; i < k.numSet; i++ {
		p.writeTag(k.tags[i][0], k.tags[i][1])
	}
	if fieldsMask&counterFieldsMask != 0 {
		p.buf = basictl.DoubleWrite(p.buf, counter)
	}
	if fieldsMask&tsFieldsMask != 0 {
		p.buf = basictl.NatWrite(p.buf, tsUnixSec)
	}
}

// returns space reserve or <0 if did not fit
func (p *packet) writeHeader(c *Client, k *metricKeyTransport, skey string, counter float64, tsUnixSec uint32, fieldsMask uint32, reserveSpace int) int {
	wasLen := len(p.buf)
	p.writeHeaderImpl(k, skey, counter, tsUnixSec, fieldsMask)
	left := p.maxSize - len(p.buf) - reserveSpace
	if left >= 0 {
		p.batchCount++
		return left
	}
	if wasLen != batchHeaderLen {
		p.buf = p.buf[:wasLen]
		if c != nil {
			c.flush()
			p.writeHeaderImpl(k, skey, counter, tsUnixSec, fieldsMask)
			left = p.maxSize - len(p.buf) - reserveSpace
			if left >= 0 {
				p.batchCount++
				return left
			}
		}
		wasLen = batchHeaderLen
	}
	p.buf = p.buf[:wasLen]
	if c != nil {
		c.rareLog("[statshouse] metric %q payload too big to fit into packet, discarding", k.name)
	}
	return -1
}

func (c *packet) writeTag(tagName string, tagValue string) {
	c.buf = basictl.StringWriteTruncated(c.buf, tagName)
	c.buf = basictl.StringWriteTruncated(c.buf, tagValue)
}

func fillTag(k *metricKeyTransport, tagName string, tagValue string) {
	if tagValue == "" || k.numSet >= maxTags { // both checks are not strictly required
		return
	}
	k.tags[k.numSet] = [2]string{tagName, tagValue}
	k.numSet++
	k.hasEnv = k.hasEnv || tagName == "0" || tagName == "env" || tagName == "key0" // TODO - keep only "0", rest are legacy
	k.hasHost = k.hasHost || tagName == "_h"                                       // TODO - remove when directly connect without balancer
}

func maxPacketSize(network string, addr string) int {
	switch network {
	case "tcp":
		return math.MaxUint16
	case "unixgram":
		return 1232
	default:
		addr, err := net.ResolveUDPAddr("udp", addr)
		switch {
		case err == nil && addr.IP.IsLoopback():
			if runtime.GOOS == "darwin" {
				return 1232 // macOS has stricter UDP limits on loopback interface
			}
			return 65507 // https://stackoverflow.com/questions/42609561/udp-maximum-packet-size/42610200
		default:
			return 1232 // IPv6 mandated minimum MTU size of 1280 (minus 40 byte IPv6 header and 8 byte UDP header)
		}
	}
}

package statshouse

import (
	"log"
	"os"
	"sync"
	"sync/atomic"
	"time"
)

type Client struct {
	// logging
	logMu sync.Mutex
	logF  LoggerFunc
	logT  time.Time // last write time, to reduce # of errors reported

	// transport
	transportMu sync.RWMutex
	app         string
	env         string // if set, will be put into key0/env
	network     string
	addr        string
	dialTargets []string // resolved "host:port" (TCP: two used in parallel; UDP: first)
	hostTag     string
	conn        netConn
	packet

	// data
	mu            sync.RWMutex // taken after [bucket.mu]
	w             map[metricKey]*bucket
	r             []*bucket
	wn            map[metricKeyNamed]*bucket
	rn            []*bucket
	tsUnixSec     uint32
	maxBucketSize int

	// external callbacks
	regularFuncsMu sync.Mutex
	regularFuncs   map[int]func(*Client)
	nextRegularID  int

	// shutdown
	closeOnce sync.Once
	closeErr  error
	close     chan chan struct{}

	// debug
	bucketCount *atomic.Int32
}

// NewClient creates a new [Client] to send metrics. Use NewClient only if you are
// sending metrics to two or more StatsHouse clusters. Otherwise, simply [Configure]
// the default global [Client].
//
// Specifying empty StatsHouse address will make the client silently discard all metrics.
// if you get compiler error after updating to recent version of library, pass statshouse.DefaultNetwork to network parameter
func NewClient(logf LoggerFunc, network string, statsHouseAddr string, defaultEnv string) *Client {
	return NewClientEx(ConfigureArgs{
		Logger:         logf,
		Network:        network,
		StatsHouseAddr: statsHouseAddr,
		DefaultEnv:     defaultEnv,
	})
}

func NewClientEx(args ConfigureArgs) *Client {
	c := &Client{
		close:        make(chan chan struct{}),
		w:            map[metricKey]*bucket{},
		wn:           map[metricKeyNamed]*bucket{},
		regularFuncs: map[int]func(*Client){},
		tsUnixSec:    uint32(time.Now().Unix()),
	}
	c.ConfigureEx(args)
	go c.run()
	return c
}

func (c *Client) ConfigureEx(args ConfigureArgs) {
	if args.Logger == nil {
		args.Logger = log.Printf
	}
	if args.Network == "" {
		args.Network = DefaultNetwork
	}
	if args.MaxBucketSize <= 0 {
		args.MaxBucketSize = defaultMaxBucketSize
	}
	// update logger
	c.logMu.Lock()
	c.logF = args.Logger
	c.logMu.Unlock()
	// update max bucket size
	c.mu.Lock()
	c.maxBucketSize = args.MaxBucketSize
	c.mu.Unlock()
	// update transport
	c.transportMu.Lock()
	defer c.transportMu.Unlock()
	c.app = args.AppName
	c.env = args.DefaultEnv
	c.network = args.Network
	c.addr = args.StatsHouseAddr
	if hostname, err := os.Hostname(); err != nil {
		args.Logger("[statshouse] failed to read hostname: %v", err)
	} else {
		c.hostTag = forceValidHostTag(hostname)
	}
	if c.conn != nil {
		err := c.conn.Close()
		if err != nil {
			args.Logger("[statshouse] failed to close connection: %v", err)
		}
		c.conn = nil
	}
	// update packet size
	if maxSize := maxPacketSize(args.Network, args.StatsHouseAddr); maxSize != c.packet.maxSize {
		c.packet = packet{
			buf:     make([]byte, batchHeaderLen, maxSize),
			maxSize: maxSize,
		}
	}
	if c.addr == "" {
		args.Logger("[statshouse] configured with empty address, all statistics will be silently dropped")
	}
}

// Close the [Client] and flush unsent metrics to the StatsHouse agent.
// No data will be sent after Close has returned.
func (c *Client) Close() error {
	c.closeOnce.Do(func() {
		ch := make(chan struct{})
		c.close <- ch
		<-ch

		c.transportMu.Lock()
		defer c.transportMu.Unlock()

		if c.conn != nil {
			c.closeErr = c.conn.Close()
		}
	})
	return c.closeErr
}

// SetEnv changes the default environment associated with [Client].
func (c *Client) SetEnv(env string) {
	c.transportMu.Lock()
	c.env = env
	c.transportMu.Unlock()
}

// For debug purposes. If necessary then it should be first method called on [Client].
func (c *Client) TrackBucketCount() {
	c.bucketCount = &atomic.Int32{}
}

// For debug purposes. Panics if [Client.TrackBucketCount] wasn't called.
func (c *Client) BucketCount() int32 {
	return c.bucketCount.Load()
}

// StartRegularMeasurement will call f once per collection interval with no gaps or drift,
// until StopRegularMeasurement is called with the same ID.
func (c *Client) StartRegularMeasurement(f func(*Client)) (id int) {
	c.regularFuncsMu.Lock()
	defer c.regularFuncsMu.Unlock()
	c.nextRegularID++
	c.regularFuncs[c.nextRegularID] = f
	return c.nextRegularID
}

// StopRegularMeasurement cancels StartRegularMeasurement with the specified ID.
func (c *Client) StopRegularMeasurement(id int) {
	c.regularFuncsMu.Lock()
	defer c.regularFuncsMu.Unlock()
	delete(c.regularFuncs, id)
}

